                  "type": "terminal",
                  "title": "Not in the directory, not on that node",
                  "text": "root@reef-cp1:~# ls /etc/kubernetes/manifests\netcd.yaml  kube-apiserver.yaml  kube-controller-manager.yaml  kube-scheduler.yaml"
